 MainActivity home;View root;DesktopStore store;ElevenMarketCard card;int checks;String live="UNAVAILABLE";final List<String> opened=new ArrayList<>();
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle out=new Bundle();try{store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean(ElevenMarket.ENABLED,false).commit();getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();
 ui(()->{card=new ElevenMarketCard(home,store,opened::add,true,(light,mode,range)->"<html><body style='background:"+(light?"white":"black")+";color:"+(light?"black":"white")+"'><h2 id='fixture'>Market display test fixture</h2><p>"+mode+" "+range+"</p><script>setInterval(function(){document.body.dataset.ticks=String(Number(document.body.dataset.ticks||0)+1);},100);function paint(){document.body.dataset.raf=String(Number(document.body.dataset.raf||0)+1);requestAnimationFrame(paint);}requestAnimationFrame(paint);</script></body></html>");overlay(card);});waitForIdleSync();check(card.web==null,"No provider WebView before opt-in");ui(()->TenSmoke.description(card,"Load market quotes and charts").performClick());await(()->card.web!=null,"Opt-in creates actual WebView");await(()->js("document.getElementById('fixture')!=null").equals("true"),"Actual fixture document renders");timerIsolation();ui(()->{WebSettings s=card.web.getSettings();check(!s.getAllowFileAccess()&&!s.getAllowContentAccess()&&!s.getAllowUniversalAccessFromFileURLs(),"Provider has no local content access");check(s.getMixedContentMode()==WebSettings.MIXED_CONTENT_NEVER_ALLOW,"Mixed content denied");card.route("file:///sdcard/private");card.route("intent://test");check(opened.isEmpty(),"Privileged navigation denied");card.route(ElevenMarket.report("Index ETFs",0));check(opened.size()==1&&opened.get(0).startsWith("favorite-web:https://"),"HTTPS opens in Nth browser route");card.active(false);check(card.web==null,"Background/hidden stops provider view");card.active(true);});await(()->card.web!=null,"Visible resumes display");int created=card.created;ui(()->{card.appearance(false);});await(()->card.created>created,"Theme rebuilds provider using new palette");ui(()->{store.prefs.edit().putString(ElevenMarket.MODE,"Indices").putString(ElevenMarket.RANGE,"3M").commit();card.refresh();});await(()->js("document.body.innerText.includes('Indices 3M')").equals("true"),"Range and symbols reach displayed document");
 DesktopBackup.Plan plan=DesktopBackup.parse(DesktopBackup.snapshot(store).toString());check(plan.string(ElevenMarket.MODE,"").equals("Indices")&&plan.string(ElevenMarket.RANGE,"").equals("3M"),"Provider choices round-trip through validated backup");ui(()->{TenSmoke.description(card,"Disable embedded market data").performClick();});await(()->card.web==null,"Disable immediately destroys provider");ui(()->{unmount();});
 categories();liveProbe();ui(()->{unmount();});try(Writer w=new FileWriter(new File(getTargetContext().getFilesDir(),"eleven-market-live.tsv"))){w.write("Provider\tOutcome\tDetail\nTradingView\t"+live+"\tOfficial iframe display probe; inspect native screenshot for quote availability. No quote data is extracted.\n");}out.putString("stream","PASS: Eleven market/category "+checks+" assertions; actual opt-in display, safe navigation/local access, symbol/range/backup, palette and hidden lifecycle, declared Start categories with real app actions, both orientations, widget controls and separately recorded live provider probe ("+live+").\n");finish(Activity.RESULT_OK,out);
 }catch(Throwable failure){try{shot("eleven-market-failure");}catch(Exception ignored){}out.putString("stream","FAIL: "+android.util.Log.getStackTraceString(failure));finish(Activity.RESULT_CANCELED,out);}finally{if(store!=null)store.prefs.edit().putBoolean(ElevenMarket.ENABLED,false).putString(ElevenMarket.MODE,"Index ETFs").putString(ElevenMarket.RANGE,"1D").putString("eleven_start_view","List").putBoolean("eleven_start_pinned",true).commit();}}
 void timerIsolation()throws Exception{await(()->!js("document.body.dataset.ticks||'0'").equals("\"0\""),"Fixture timer starts");ui(()->{home.open("@browser");BrowserPanel browser=TenSmoke.find(root,BrowserPanel.class);View parent=browser;while(parent!=null&&!(parent instanceof DesktopWindow))parent=parent.getParent() instanceof View?(View)parent.getParent():null;check(parent instanceof DesktopWindow,"Browser has actual window");((DesktopWindow)parent).minimize();});int before=Integer.parseInt(js("Number(document.body.dataset.ticks||0)"));Thread.sleep(500);await(()->{try{return Integer.parseInt(js("Number(document.body.dataset.ticks||0)"))>before;}catch(Exception e){return false;}},"Minimizing browser leaves market timers running");int raf=Integer.parseInt(js("Number(document.body.dataset.raf||0)"));Thread.sleep(150);await(()->{try{return Integer.parseInt(js("Number(document.body.dataset.raf||0)"))>raf;}catch(Exception e){return false;}},"Market animation frames continue after browser minimization");}
 void categories()throws Exception{ui(()->{store.prefs.edit().putString("eleven_start_view","Category").putBoolean("eleven_start_pinned",false).putBoolean("eleven_start_recent",false).putBoolean("eleven_start_added",false).putBoolean("eleven_start_files",false).putBoolean("eleven_start_all",true).commit();home.open("start-menu:");});await(()->TenSmoke.description(root,"All apps categories")!=null,"Recorded Category view exists");for(int o:new int[]{ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE}){ui(()->{home.setRequestedOrientation(o);home.open("start-menu:");});waitForIdleSync();check(TenSmoke.description(root,"Start category Productivity")!=null,"Category retained after orientation");shot(o==1?"eleven-category-portrait":"eleven-category-landscape");}ui(()->{TenSmoke.description(root,"Start category Productivity").performClick();});systemClick("Open Notepad");await(()->TenSmoke.description(root,"Notepad text")!=null,"Category app launches actual Notepad");ui(()->{home.open("@news");TenNews news=TenSmoke.find(root,TenNews.class);news.widgetsOnly=true;news.render();});await(()->TenSmoke.description(root,"Options for markets widget")!=null,"Per-card options reachable");}
 void liveProbe()throws Exception{ui(()->home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));waitForIdleSync();Thread.sleep(300);List<String> outcomes=new ArrayList<>();for(String mode:ElevenMarket.MODES){ui(()->{store.prefs.edit().putBoolean(ElevenMarket.ENABLED,true).putString(ElevenMarket.MODE,mode).putString(ElevenMarket.RANGE,"1M").commit();card=new ElevenMarketCard(home,store,opened::add,true);overlay(card);});await(()->card.web!=null||card.engineBlocked,"Official market embed starts");String result="UNAVAILABLE";long end=SystemClock.uptimeMillis()+20000;while(SystemClock.uptimeMillis()<end){if(card.engineBlocked){result="WEBVIEW_UPDATE_REQUIRED";break;}if(js("document.querySelector('iframe')!=null").equals("true")){result="FRAME_OPENED";break;}Thread.sleep(350);}Thread.sleep(15000);if(card.engineBlocked)result="WEBVIEW_UPDATE_REQUIRED";outcomes.add(mode+": "+result);shot(mode.equals("Indices")?"eleven-market-live-indices":"eleven-market-live");try(Writer log=new FileWriter(new File(getTargetContext().getFilesDir(),mode.equals("Indices")?"eleven-market-indices-console.txt":"eleven-market-etfs-console.txt"))){log.write(card.diagnostics.toString());}ui(()->{card.active(false);check(card.web==null,"Live provider destroyed on hide");unmount();});}live=String.join("; ",outcomes);ui(()->{card=new ElevenMarketCard(home,store,opened::add,true);overlay(card);card.active(false);});}

 void systemClick(String name)throws Exception{await(()->node(getUiAutomation().getRootInActiveWindow(),name)!=null,"Category action available: "+name);AccessibilityNodeInfo item=node(getUiAutomation().getRootInActiveWindow(),name);Rect bounds=new Rect();item.getBoundsInScreen(bounds);long down=SystemClock.uptimeMillis();for(int action:new int[]{0,1}){MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,bounds.centerX(),bounds.centerY(),0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(event,true),"Actual category-list touch");event.recycle();}waitForIdleSync();}
 AccessibilityNodeInfo node(AccessibilityNodeInfo item,String name){if(item==null)return null;if(name.contentEquals(item.getText()==null?"":item.getText())||name.contentEquals(item.getContentDescription()==null?"":item.getContentDescription()))return item;for(int i=0;i<item.getChildCount();i++){AccessibilityNodeInfo found=node(item.getChild(i),name);if(found!=null)return found;}return null;}
 void unmount(){card.close();ViewGroup holder=(ViewGroup)card.getParent();if(holder!=null&&holder.getParent() instanceof ViewGroup)((ViewGroup)holder.getParent()).removeView(holder);}
 void overlay(View v){FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,-1);ScrollView scroll=new ScrollView(home);scroll.setFillViewport(false);scroll.setContentDescription("Market test display");scroll.addView(v,new ScrollView.LayoutParams(-1,-2));((FrameLayout)home.findViewById(android.R.id.content)).addView(scroll,p);}
 String js(String expression){try{CountDownLatch latch=new CountDownLatch(1);String[] result={""};ui(()->{if(card.web==null){latch.countDown();return;}card.web.evaluateJavascript(expression,value->{result[0]=value;latch.countDown();});});if(!latch.await(4,TimeUnit.SECONDS))return "";return result[0];}catch(Exception e){return "";}}
 void await(BooleanSupplier ready,String message)throws Exception{long until=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<until){if(ready.getAsBoolean()){checks++;return;}Thread.sleep(80);}throw new AssertionError(message);}
 void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}void ui(Runnable task)throws Exception{FutureTask<Void> f=new FutureTask<>(task,null);home.runOnUiThread(f);f.get(25,TimeUnit.SECONDS);}void shot(String name)throws Exception{waitForIdleSync();ui(()->{Bitmap image=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(image));try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+"-view.png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}catch(IOException e){throw new RuntimeException(e);}finally{image.recycle();}});Bitmap image=getUiAutomation().takeScreenshot();if(image!=null)try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}}
